# Recibe modelos históricos y conexión; normaliza carreras, inscribe a líderes aprobados y conecta avales antiguos con su DM oficial.
def preparar_datos(apps, schema_editor):
    alias = schema_editor.connection.alias
    Usuario = apps.get_model('core', 'Usuario')
    Club = apps.get_model('core', 'Club')
    Membresia = apps.get_model('core', 'MembresiaClub')
    Aval = apps.get_model('core', 'AvalClub')
    Mensaje = apps.get_model('core', 'MensajeDirecto')
    Inbox = apps.get_model('core', 'MensajeInbox')
    for carrera in ('Ing. Informática', 'Ing. Diseño', 'Ing. Mecánica'):
        Usuario.objects.using(alias).filter(carr_usu=carrera + ' (4 años)').update(carr_usu=carrera)
    for club in Club.objects.using(alias).filter(est_club='APROBADO'):
        Membresia.objects.using(alias).get_or_create(club_memb_id=club.pk, usu_memb_id=club.lid_club_id)
    sistema = Usuario.objects.using(alias).filter(username='sistema').first()
    if sistema:
        for aval in Aval.objects.using(alias).select_related('club_aval'):
            if Mensaje.objects.using(alias).filter(aval_mens_id=aval.pk).exists():
                continue
            aviso = Inbox.objects.using(alias).filter(club_inbo_id=aval.club_aval_id, dest_inbo_id=aval.estu_aval_id, tipo_inbo='SOLICITUD_AVAL').first()
            previo = Mensaje.objects.using(alias).filter(emi_mens_id=sistema.pk, rec_mens_id=aval.estu_aval_id, aval_mens__isnull=True, cont_mens=f'{aviso.asun_inbo}\n{aviso.cuer_inbo}').first() if aviso else None
            texto = f'Solicitud de aval para «{aval.club_aval.nom_club}». Responde aquí. Avalar no te inscribe automáticamente al club.'
            if previo:
                previo.aval_mens_id, previo.cont_mens = aval.pk, texto
                previo.save(using=alias, update_fields=['aval_mens', 'cont_mens'])
            else:
                Mensaje.objects.using(alias).create(emi_mens_id=sistema.pk, rec_mens_id=aval.estu_aval_id, aval_mens_id=aval.pk, cont_mens=texto)


